public class cf1342e{
    static int MOD = 998244353;

    public static void main(String[] args) throws IOException {
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tk = new StringTokenizer(in.readLine());
        int n = Integer.parseInt(tk.nextToken());
        long k = Long.parseLong(tk.nextToken());
        if (k > n) {
            out.println(0);
            out.close();
            return;
        }
        int a = n - (int) k;
        long comb = 1;
        long res = 0;
        for (int i = a; i >= 1; i--) {
            int sign = ((a - i) & 1) == 0 ? 1 : -1;
            res += sign * comb * pow(i, n);
            res %= MOD;
            res = (res + MOD) % MOD;
            comb = (comb * i) % MOD;
            comb = (comb * pow(a - i + 1, MOD - 2)) % MOD;
        }
        a = Math.max(a, (int) k);
        for (int i = a + 1; i <= n; i++) {
            res = (res * i) % MOD;
        }
        for (int i = 1; i <= n - a; i++) {
            res = (res * pow(i, MOD - 2)) % MOD;
        }
        if (k != 0) {
            res = (res * 2) % MOD;
        }
        out.println(res);
        out.close();
    }

    public static long pow(long a, long e) {
        if (e == 0) return 1;
        long half = pow(a, e / 2);
        half = half * half % MOD;
        if ((e & 1) == 1) half = half * a % MOD;
        return half;
    }
}
